pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address log1, address log2, uint256 minSum) public {
        vm.assume(log1 != address(0));
        vm.assume(log2 != address(0));
        vm.assume(log1 != log2);
        vm.assume(minSum > 0);

        // Deploy two log file contracts
        LogFile lf1 = new LogFile();
        LogFile lf2 = new LogFile();

        // Initialize C
        c.SetMinSum(minSum);
        c.SetLogFile(address(lf1));
        c.Initialized();

        // Deposit to generate a log entry
        vm.deal(address(this), 1 ether);
        c.Deposit{value: 1 ether}();

        // Record the Log address before a potential second SetLogFile call
        LogFile logBefore = LogFile(address(uint160(uint256(keccak256(abi.encodePacked(address(c).code, bytes1(0x01))))))); // dummy, we use address(getLogBeforeHelper())
        // We cannot read private Log directly. Instead we check if the initial logs exist in lf1.
        // The core property: after full initialization, calling SetLogFile again either reverts (correct)
        // or succeeds (bug) and changes the Log address. The correct contract preserves the original Log address
        // and still logs to it. We verify by checking that lf1 has exactly 1 message after Deposit.

        // Try to change Log after initialization
        try c.SetLogFile(address(lf2)) {
            // Buggy case: SetLogFile succeeded, Log was changed.
            // The property: If SetLogFile succeeds after initialization, the change is reflected in future logs.
            // But the original contract invariant is that SetLogFile reverts after initialization.
            // The universal property: the Log address cannot be changed after initialization.
            // We detect the change: if SetLogFile succeeded, then Log was changed.
            // We check a deposit to the new log.
            vm.deal(address(this), 1 ether);
            c.Deposit{value: 1 ether}();
            // In buggy version, latest message is in lf2; in correct version, this code path is unreachable (reverted).
            // The property: the original LogFile's history length after initialization must remain consistent
            // with the number of deposits made (1 deposit before the second SetLogFile attempt).
            // But if SetLogFile succeeds, the Log state variable changes, meaning the previous Log is detached.
            // The invariant: after Initialized(), Log is immutable.
            // We capture that by checking that lf1.History length is still exactly 1.
            // If SetLogFile succeeded, future deposits go to lf2, but lf1 still has 1 entry.
            // The difference: In correct version, SetLogFile reverts, so we never reach this branch.
            // To make a single assertion that holds for correct and fails for buggy:
            // If SetLogFile does NOT revert, then the Log address has been changed, violating the immutability.
            // We assert that the setLogFile call reverted (correct) or if it didn't, the Log contract's last message
            // sender is not address(0) (always true). This doesn't work.
            // Better approach: The correct contract's invariant is: after Initialized(), calling SetLogFile always reverts.
            // We capture this with a bool flag.
            // Since we cannot assert directly on Log without a public getter, we use the fact that LogFile's AddMessage
            // is only callable by C. If Log was changed, then lf2 gets messages.
            // We assert that lf2.History length is 1 (indicating SetLogFile succeeded and changed Log).
            // But in correct contract, this branch never runs because SetLogFile reverts.
            // The property: If SetLogFile after initialization does not revert, then the Log address is updated.
            // To make it universal: In the correct contract, after Initialized(), SetLogFile always reverts.
            // So the assertTrue can check that the reversion happened.
            // We need a single assertion that passes on correct and fails on buggy.
            // Simplest: wrap SetLogFile in try/catch, and assert that it reverted (ok == false).
            // But we are already in the success path of try/catch.
            // Let's restructure.
        } catch {
            // Correct behavior: SetLogFile reverted.
            // Deposit again, should log to lf1.
            vm.deal(address(this), 1 ether);
            c.Deposit{value: 1 ether}();
        }

        // After the scenario, the invariant: The Log address after initialization is immutable.
        // The correct contract's behavior: the second SetLogFile call reverts, and lf1 has 2 messages.
        // The buggy contract's behavior: the second SetLogFile succeeds, and lf1 has 1 message, lf2 has 1.
        // Universal property: The number of messages in the original LogFile (lf1) equals the total number of deposits made.
        // In correct: 2 deposits -> lf1.History.length == 2.
        // In buggy: 2 deposits, but second deposit went to lf2 -> lf1.History.length == 1.
        // Therefore property: lf1.History.length == totalDeposits (which is 2 in this test).
        // But the fuzzer sets minSum and addresses. The number of deposits is fixed in test (2).
        // That would work but "totalDeposits" is hardcoded.
        // We need the property to depend on the fuzzed parameters.
        // Let's fuzz the number of deposits? We can loop but that's complex.
        // Alternative: The correct contract's invariant: Log is immutable after Initialized().
        // The bug has no such immutability. The property: after Initialized(), any call to SetLogFile reverts.
        // This is a simple revert property.
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

