        // Since the fuzzer cannot synthesize a failing callee from a raw address,
        // but the difference does not require a failing external call, we simply call Collect as the caller.
        vm.prank(caller);
        try c.Collect(amtToCollect) {
            // If it did not revert, balance must have decreased.
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter < balanceBefore);
        } catch {
            // If it reverted, the invariant holds vacuously.
        }
    }
}
